<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/assets/css/app.css"><style>body{background:#f5f7fb}.page{max-width:980px;margin:auto;padding:28px 18px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:18px;padding:24px;box-shadow:0 8px 30px rgba(15,23,42,.06)}.grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}label{display:block;font-size:13px;font-weight:700;margin-bottom:6px}input{width:100%;padding:12px;border:1px solid #dbe1ea;border-radius:10px}button,.btn{border:0;border-radius:10px;padding:12px 17px;background:#2563eb;color:#fff;text-decoration:none;font-weight:700;cursor:pointer}.secondary{background:#eef2f7;color:#0f172a}.full{grid-column:1/-1}.muted{color:#64748b}.error{color:#b91c1c}.success{color:#047857}@media(max-width:700px){.grid{grid-template-columns:1fr}.full{grid-column:auto}.top{align-items:flex-start;gap:10px;flex-direction:column}}</style><title>Add Customer · ISPLUKA</title></head><body><main class="page"><div class="top"><div><h1>Add Customer</h1><p class="muted">Create a new subscriber account in your ISP tenant.</p></div><a class="btn secondary" href="/">Dashboard</a></div><section class="card"><form id="form"><input type="hidden" name="_csrf" value="<?=$token?>"><div class="grid"><div><label>Customer Code *</label><input name="customer_code" required placeholder="CUS-0001"></div><div><label>Customer Name *</label><input name="name" required></div><div><label>Phone</label><input name="phone" inputmode="tel"></div><div><label>Email</label><input name="email" type="email"></div><div><label>NID</label><input name="nid"></div><div><label>Area</label><input name="area"></div><div class="full"><label>Address</label><input name="address"></div><div><label>Billing Day</label><input name="billing_day" type="number" min="1" max="28" value="1"></div><div><label>Credit Limit</label><input name="credit_limit" type="number" min="0" step="0.01" value="0"></div></div><button type="submit" style="margin-top:18px">Create Customer</button><p id="msg"></p></form></section></main><script>const f=document.getElementById('form'),m=document.getElementById('msg');f.onsubmit=async e=>{e.preventDefault();m.textContent='Creating…';m.className='muted';const r=await fetch('/api/customers',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(new FormData(f))});const j=await r.json();if(!r.ok){m.textContent=j.error?.message||'Unable to create customer.';m.className='error';return}m.textContent='Customer created successfully. ID: '+j.data.id;m.className='success';f.reset()};</script></body></html>